var GLOSSARY=[{"id": "abba", "t": "Abba", "d": "An Aramaic word for “father”, used as a title of respect for an experienced monk, especially among the Desert Fathers. The female form is Amma.", "f": ["Abba"]}, {"id": "anchorite", "t": "Anchorite", "d": "A Christian who withdraws from society to live alone in prayer, as many early desert monks did. Compare coenobitic.", "f": ["anchorite", "anchorites", "Anchorite", "Anchorites"]}, {"id": "anf", "t": "ANF (Ante-Nicene Fathers)", "d": "A ten-volume English translation of early Christian writings before the Council of Nicaea (325), edited by Alexander Roberts and James Donaldson (1867–1873; American edition 1885–1896). Several texts on this site come from it.", "f": ["ANF"]}, {"id": "ante-nicene", "t": "Ante-Nicene", "d": "Belonging to the period before the Council of Nicaea in 325.", "f": ["Ante-Nicene", "ante-Nicene"]}, {"id": "apologist", "t": "Apologist", "d": "An early Christian writer who defended the faith in writing to outsiders, such as Roman rulers or philosophers. St Justin Martyr is a well-known example. The word comes from the Greek apologia, “defence”.", "f": ["apologist", "apologists", "Apologist", "Apologists"]}, {"id": "apostolic-fathers", "t": "Apostolic Fathers", "d": "The earliest Christian writers after the New Testament, traditionally thought to have known the apostles or their disciples. They include St Clement of Rome, St Ignatius of Antioch and the author of the Didache.", "f": ["Apostolic Fathers"]}, {"id": "arianism", "t": "Arianism", "d": "The teaching of Arius, a priest of Alexandria (died 336), that the Son of God was created and is not fully equal to the Father. It was rejected at the Council of Nicaea in 325.", "f": ["Arianism", "Arians", "Arian", "Arius"]}, {"id": "asceticism", "t": "Asceticism", "d": "Spiritual discipline such as fasting, vigils, simple living and self-denial, practised to grow in prayer and virtue. From the Greek askesis, “exercise” or “training”.", "f": ["asceticism", "ascetic", "ascetics", "Asceticism"]}, {"id": "cappadocian-fathers", "t": "Cappadocian Fathers", "d": "St Basil the Great, his brother St Gregory of Nyssa and their friend St Gregory of Nazianzus, fourth-century bishops from Cappadocia (in modern Turkey) who shaped the doctrine of the Trinity.", "f": ["Cappadocian Fathers", "Cappadocians"]}, {"id": "catechumen", "t": "Catechumen", "d": "Someone receiving instruction in the Christian faith in preparation for baptism.", "f": ["catechumen", "catechumens", "Catechumen", "Catechumens"]}, {"id": "chalcedon", "t": "Chalcedon, Council of", "d": "The church council held in 451 that taught that Christ is one person in two natures, divine and human.", "f": ["Chalcedon"]}, {"id": "church-fathers", "t": "Church Fathers", "d": "Influential teachers and writers of the early Church, roughly from the first to the eighth century, whose works shaped Christian belief and worship. Their study is called patristics.", "f": ["Church Fathers"]}, {"id": "church-of-the-east", "t": "Church of the East", "d": "The ancient Christian church of the Persian Empire and beyond, which used Syriac. St Isaac the Syrian belonged to it.", "f": ["Church of the East"]}, {"id": "coenobitic", "t": "Coenobitic", "d": "Describing monks who live together in a community under a common rule, rather than alone. From the Greek for “common life”.", "f": ["coenobitic", "cenobitic", "coenobites", "cenobites"]}, {"id": "desert-fathers", "t": "Desert Fathers", "d": "Christian monks and hermits of the Egyptian, Palestinian and Syrian deserts, especially from the third to fifth centuries. Their sayings were collected and widely read. St Anthony the Great is the best known.", "f": ["Desert Fathers"]}, {"id": "docetism", "t": "Docetism", "d": "The early belief that Christ only seemed to have a real human body and did not truly suffer. St Ignatius of Antioch wrote against it. From the Greek dokein, “to seem”.", "f": ["Docetism", "Docetae", "Docetists"]}, {"id": "doctor-of-the-church", "t": "Doctor of the Church", "d": "A title given by the Catholic Church to saints recognised for the importance of their teaching. Augustine, Athanasius, Basil, John Chrysostom and John of Damascus are among them. The Orthodox Church honours Basil, Gregory the Theologian and John Chrysostom as the “Three Holy Hierarchs and Universal Teachers”.", "f": ["Doctor of the Church", "Doctors of the Church"]}, {"id": "ecumenical-council", "t": "Ecumenical council", "d": "A gathering of bishops from across the Christian world to settle questions of belief, such as Nicaea (325) and Chalcedon (451).", "f": ["ecumenical council", "Ecumenical Council", "ecumenical councils"]}, {"id": "eucharist", "t": "Eucharist", "d": "The central sacrament of the Church, in which the faithful receive the true Body and Blood of Christ; celebrated in the Orthodox Church as the Divine Liturgy (in the West, the Mass). From the Greek eucharistia, “thanksgiving”.", "f": ["Eucharist", "eucharist"]}, {"id": "gnosticism", "t": "Gnosticism", "d": "A modern name for various second-century movements that taught salvation through secret knowledge (gnosis) and often regarded the material world as evil. St Irenaeus wrote Against Heresies to answer them.", "f": ["Gnosticism", "Gnostics", "Gnostic"]}, {"id": "heresy", "t": "Heresy", "d": "A teaching that the Church judged to contradict its essential beliefs. From the Greek hairesis, “choice” or “faction”.", "f": ["heresy", "heresies"]}, {"id": "hesychasm", "t": "Hesychasm", "d": "A tradition of prayer in Eastern Christianity centred on inner stillness and the repeated Jesus Prayer. From the Greek hesychia, “stillness” or “quiet”.", "f": ["hesychasm", "Hesychasm", "hesychia", "hesychast", "hesychasts"]}, {"id": "hexaemeron", "t": "Hexaemeron", "d": "Greek for “six days”: a commentary on the six days of creation in Genesis 1, such as the nine homilies of St Basil the Great.", "f": ["Hexaemeron", "Hexæmeron"]}, {"id": "homoousios", "t": "Homoousios", "d": "Greek for “of the same essence”. The Nicene Creed uses it to say the Son is of one substance with the Father.", "f": ["homoousios", "Homoousios", "homoousion"]}, {"id": "hypostasis", "t": "Hypostasis", "d": "A Greek word meaning “substance” or “subsistence”. The Cappadocian Fathers used it for each of the three persons of the Trinity: one essence (ousia) in three hypostases. In Christ, the one hypostasis of the Son unites the divine and human natures.", "f": ["hypostasis", "hypostases", "Hypostasis", "Hypostases"]}, {"id": "icon", "t": "Icon", "d": "A holy image of Christ, Mary or the saints, painted in a traditional style and venerated in Christian worship, especially in the Eastern churches. St John of Damascus defended their use.", "f": ["icon", "icons"]}, {"id": "iconoclasm", "t": "Iconoclasm", "d": "The eighth- and ninth-century controversy over destroying or forbidding holy images. The Second Council of Nicaea (787) upheld the veneration of icons.", "f": ["iconoclasm", "Iconoclasm", "iconoclasts", "Iconoclasts"]}, {"id": "incarnation", "t": "Incarnation", "d": "The Christian belief that the eternal Son of God became human in Jesus Christ. From the Latin for “taking flesh”.", "f": ["Incarnation"]}, {"id": "liturgy", "t": "Liturgy", "d": "The public worship of the Church, especially the order of the Eucharist. From the Greek leitourgia, “public service”.", "f": ["liturgy", "Liturgy"]}, {"id": "logos", "t": "Logos", "d": "Greek for “word” or “reason”. In John 1:1 and the Fathers it names the eternal Son of God, the Word.", "f": ["Logos"]}, {"id": "manichaeism", "t": "Manichaeism", "d": "A religion founded by Mani in third-century Persia that taught a struggle between two equal powers of light and darkness. Augustine followed it for some years before his conversion.", "f": ["Manichaeism", "Manichees", "Manichæans", "Manichaeans", "Manichee", "Manichæus"]}, {"id": "martyr", "t": "Martyr", "d": "Someone who is put to death for their faith. From the Greek martys, “witness”.", "f": ["martyrdom"]}, {"id": "monasticism", "t": "Monasticism", "d": "A way of Christian life withdrawn from the world and devoted to prayer, either alone or in community.", "f": ["monasticism", "Monasticism"]}, {"id": "nestorianism", "t": "Nestorianism", "d": "A view associated with Nestorius, Archbishop of Constantinople (died c. 451), which was condemned at the Council of Ephesus (431) for dividing Christ into two persons and refusing to call Mary Theotokos.", "f": ["Nestorianism", "Nestorius", "Nestorians"]}, {"id": "nicaea", "t": "Nicaea, Council of", "d": "The first ecumenical council, held in 325 at Nicaea (modern İznik, Turkey). It rejected Arianism and produced the first form of the Nicene Creed.", "f": ["Nicaea", "Nicæa"]}, {"id": "nicene-creed", "t": "Nicene Creed", "d": "The statement of faith from the Councils of Nicaea (325) and Constantinople (381), still recited in many churches today.", "f": ["Nicene Creed", "Nicene"]}, {"id": "nous", "t": "Nous", "d": "Greek for “mind” or “intellect”. In the Fathers it often means the highest part of the soul, by which a person knows God and prays.", "f": ["nous"]}, {"id": "npnf", "t": "NPNF (Nicene and Post-Nicene Fathers)", "d": "A 28-volume English translation series edited by Philip Schaff and Henry Wace (1886–1900), Series 1: Augustine and Chrysostom. Series 2: Greek and Latin Fathers from the 4th to the 8th century, including Athanasius, the Cappadocians and John of Damascus. Several texts on this site come from it.", "f": ["NPNF"]}, {"id": "orthodox", "t": "Orthodox", "d": "Meaning “right belief”. It describes teaching held to be true, and is also the name of the Eastern Orthodox Church.", "f": []}, {"id": "ousia", "t": "Ousia", "d": "Greek for “essence” or “being”. The Fathers confess that the Father, the Son and the Holy Spirit share one ousia. Compare hypostasis and homoousios.", "f": ["ousia", "Ousia"]}, {"id": "pascha", "t": "Pascha", "d": "The feast of Christ’s Resurrection (Easter). From the Hebrew pesach, Passover.", "f": ["Pascha"]}, {"id": "patristic", "t": "Patristic", "d": "Relating to the Church Fathers. Patristics is the study of their lives and writings.", "f": ["patristic", "Patristic", "patristics", "Patristics"]}, {"id": "pelagianism", "t": "Pelagianism", "d": "The teaching associated with the monk Pelagius (c. 354 – c. 418) that human beings can avoid sin and live righteously by their own free will, without needing God’s grace. Augustine opposed it.", "f": ["Pelagianism", "Pelagians", "Pelagius"]}, {"id": "presbyter", "t": "Presbyter", "d": "An elder of the early Church. The English word “priest” comes from it.", "f": ["presbyter", "presbyters", "Presbyters"]}, {"id": "septuagint", "t": "Septuagint", "d": "The Greek translation of the Hebrew Scriptures made before Christ. Most early Christians read the Old Testament in this version.", "f": ["Septuagint"]}, {"id": "theosis", "t": "Theosis", "d": "The Christian hope of being united with God and sharing in his life by grace, also called deification. It is a major theme in Eastern Christian teaching.", "f": ["theosis", "Theosis", "deification"]}, {"id": "theotokos", "t": "Theotokos", "d": "Greek for “God-bearer”, a title for Mary affirmed at the Council of Ephesus (431). It expresses that the one she bore is God the Son made man.", "f": ["Theotokos"]}, {"id": "trinity", "t": "Trinity", "d": "The Christian belief in one God in three persons: Father, Son and Holy Spirit.", "f": ["Trinity"]}];
